import {nailSilhouette} from './nail-icons.js';
import {previewCanvas} from './objects.js';
export function createEditorNavigation(root,open){
 const left=root.querySelector('.polish-zone'),right=root.querySelector('.tool-zone');
 const nail=document.createElement('button');nail.className='nail-entry';nail.dataset.preview='nail';nail.dataset.section='nail';nail.setAttribute('aria-label','NAIL — shape and length');nail.innerHTML='<span class="category">nail <span>↗</span></span><span class="nail-samples">'+['natural','square','almond','stiletto'].map(nailSilhouette).join('')+'</span><span class="entry-caption">shape · length</span>';nail.onclick=()=>open('nail');left.prepend(nail);
 const old=left.querySelector(':scope > .category'),color=document.createElement('button');color.className='category category-entry color-entry';color.dataset.section='color';color.textContent='color ↗';color.setAttribute('aria-label','COLOR — polish library');color.onclick=()=>open('color');old.replaceWith(color);
 const finish=root.querySelector('.material-row'),finishLabel=finish.querySelector('.category'),finishButton=document.createElement('button');finishButton.className='category category-entry';finishButton.dataset.section='finish';finishButton.textContent='finish ↗';finishButton.setAttribute('aria-label','FINISH — polish materials');finishButton.onclick=()=>open('finish');finishLabel.replaceWith(finishButton);
 const toolsLabel=right.querySelector(':scope > .category'),toolsButton=document.createElement('button');toolsButton.className='category category-entry';toolsButton.textContent='tools';toolsButton.setAttribute('aria-label','TOOLS — painting tools');toolsButton.onclick=()=>open('tools');toolsLabel.replaceWith(toolsButton);
 const objects=document.createElement('section');objects.className='objects-entry';objects.setAttribute('aria-label','Objects library');const title=document.createElement('button');title.className='category category-entry';title.dataset.section='objects';title.textContent='objects ↗';title.setAttribute('aria-label','OBJECTS — decoration library');title.onclick=()=>open('objects');objects.append(title);const tray=document.createElement('div');tray.className='discovery-tray';
 for(const [key,label,config] of [['crystals','crystals',{type:'gem',shape:'statement',color:'#dcd9e5',finish:'ab'}],['stickers','stickers',{type:'sticker',motif:'star',color:'#514b43'}],['metal','metal',{type:'steel-bead',finish:'silver'}]]){const b=document.createElement('button');b.dataset.preview=key;b.dataset.objectCategory=key;b.setAttribute('aria-label','OBJECTS — '+label);b.append(previewCanvas(config));const span=document.createElement('span');span.textContent=label;b.append(span);b.onclick=()=>open('objects',key);tray.append(b);}objects.append(tray);right.prepend(objects);
 const stamp=root.querySelector('[data-tool=stamp]');stamp.className='transfer-entry';stamp.setAttribute('aria-label','Transfer design between nails');stamp.querySelector('.tool-label').textContent='transfer design ↗';stamp.querySelector('.implement').hidden=true;right.append(stamp);
 
 return {select(panel){root.querySelectorAll('[data-section]').forEach(b=>b.setAttribute('aria-expanded',String(b.dataset.section===panel)));},category(key){root.querySelectorAll('[data-object-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.objectCategory===key)));}};
}
